<?php
session_start();
$configFile = __DIR__ . '/config.php';
if (!file_exists($configFile)) { http_response_code(503); exit('Setup required: copy config.example.php to config.php and configure MySQL.'); }
$config = require $configFile;
try { $db = new PDO('mysql:host='.$config['host'].';dbname='.$config['database'].';charset=utf8mb4',$config['username'],$config['password'],[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC]); } catch(PDOException $e) { http_response_code(503); exit('Database unavailable.'); }
function h($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
if(!isset($_SESSION['cart'])) $_SESSION['cart']=[];
if($_SERVER['REQUEST_METHOD']==='POST' && isset($_POST['add_id'])) { $id=(int)$_POST['add_id'];$s=$db->prepare('SELECT id FROM products WHERE id=? AND is_available=1');$s->execute([$id]);if($s->fetch()) $_SESSION['cart'][$id]=min(99,($_SESSION['cart'][$id]??0)+1);header('Location: index.php#menu');exit; }
$products=$db->query('SELECT p.*,c.name category FROM products p JOIN categories c ON c.id=p.category_id WHERE p.is_available=1 ORDER BY p.is_special DESC,p.id')->fetchAll();
$cartCount=array_sum($_SESSION['cart']);
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>The Yummy House | Food & Asian Finds</title><link rel="stylesheet" href="assets/style.css"></head><body><header class="top"><a class="brand" href="index.php">The Yummy House</a><nav class="nav"><a href="#menu">Menu & Shop</a><a href="#specials">Specials</a><a href="cart.php">Cart (<?= $cartCount ?>)</a></nav></header><section class="hero"><div class="eyebrow">Potchefstroom · Die Bult</div><h1>Something delicious awaits.</h1><p>Explore comforting Asian-inspired meals, refreshing drinks and unique grocery finds. Order ahead for pickup or delivery.</p><a class="button" href="#menu">Explore the menu</a></section><main class="container"><section id="specials"><span class="eyebrow">What's cooking</span><h2>Weekly specials</h2><p class="muted">Special offers are managed by the restaurant. Sample products shown until confirmed.</p></section><section id="menu"><h2>Menu & Shop</h2><div class="grid"><?php foreach($products as $p): ?><article class="product"><div class="art" aria-hidden="true"><?= match($p['category']){'Meals'=>'🍜','Boba & Drinks'=>'🧋','Asian Groceries'=>'🍙',default=>'🥢'} ?></div><div class="info"><?php if($p['is_special']): ?><span class="pill">Weekly special</span><?php endif; ?><p class="muted"><?= h($p['category']) ?></p><h3><?= h($p['name']) ?></h3><p class="muted"><?= h($p['description']) ?></p><div class="row"><span class="price">R<?= number_format($p['price'],2) ?></span><form method="post"><input type="hidden" name="add_id" value="<?= (int)$p['id'] ?>"><button type="submit">Add +</button></form></div></div></article><?php endforeach; ?></div></section></main><footer>© <?= date('Y') ?> The Yummy House · Prototype</footer></body></html>
